using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Text;
using System.Windows.Forms;

// A lossless JSON tree: numeric lexemes and object member order are preserved.
public class Json {
    public string Kind, Value;
    public List<KeyValuePair<string, Json>> Members = new List<KeyValuePair<string, Json>>();
    public List<Json> Items = new List<Json>();
    string source; int pos;
    public static Json Parse(string text) { var p = new Json {source=text}; var v=p.Read(0); p.White(); if(p.pos!=text.Length) p.Fail("Unexpected trailing content"); return v; }
    void White(){ while(pos<source.Length && (source[pos]==' '||source[pos]=='\t'||source[pos]=='\r'||source[pos]=='\n'))pos++; }
    void Fail(string message){int line=1,col=1;for(int i=0;i<pos&&i<source.Length;i++){if(source[i]=='\n'){line++;col=1;}else col++;}throw new FormatException(message+" (line "+line+", column "+col+")");}
    bool Eat(char c){White();if(pos<source.Length&&source[pos]==c){pos++;return true;}return false;}
    void Need(char c){if(!Eat(c))Fail("Expected '"+c+"'");}
    string Str(){White();if(pos>=source.Length||source[pos++]!='"')Fail("Expected string");var b=new StringBuilder();while(pos<source.Length){char c=source[pos++];if(c=='"')return b.ToString();if(c<32)Fail("Unescaped control character");if(c!='\\'){b.Append(c);continue;}if(pos>=source.Length)Fail("Incomplete escape");c=source[pos++];switch(c){case '"':case '\\':case '/':b.Append(c);break;case 'b':b.Append('\b');break;case 'f':b.Append('\f');break;case 'n':b.Append('\n');break;case 'r':b.Append('\r');break;case 't':b.Append('\t');break;case 'u':if(pos+4>source.Length)Fail("Incomplete Unicode escape");int n;if(!int.TryParse(source.Substring(pos,4),NumberStyles.HexNumber,CultureInfo.InvariantCulture,out n))Fail("Invalid Unicode escape");b.Append((char)n);pos+=4;break;default:Fail("Invalid escape");break;}}Fail("Unterminated string");return null;}
    Json Read(int depth){if(depth>200)Fail("JSON nesting exceeds 200 levels");White();if(pos>=source.Length)Fail("Expected JSON value");var v=new Json();char c=source[pos];if(c=='{' ){pos++;v.Kind="object";var names=new HashSet<string>(StringComparer.Ordinal);if(Eat('}'))return v;do{string key=Str();if(!names.Add(key))Fail("Duplicate property: "+key);Need(':');v.Members.Add(new KeyValuePair<string,Json>(key,Read(depth+1)));}while(Eat(','));Need('}');return v;}if(c=='['){pos++;v.Kind="array";if(Eat(']'))return v;do{v.Items.Add(Read(depth+1));}while(Eat(','));Need(']');return v;}if(c=='"'){v.Kind="string";v.Value=Str();return v;}foreach(string lit in new[]{"true","false","null"})if(source.Substring(pos).StartsWith(lit,StringComparison.Ordinal)){pos+=lit.Length;v.Kind=lit=="null"?"null":"boolean";v.Value=lit;return v;}int start=pos;if(c=='-')pos++;if(pos>=source.Length)Fail("Invalid number");if(source[pos]=='0')pos++;else {if(source[pos]<'1'||source[pos]>'9')Fail("Expected JSON value");while(pos<source.Length&&source[pos]>='0'&&source[pos]<='9')pos++;}if(pos<source.Length&&source[pos]=='.'){pos++;Digits();}if(pos<source.Length&&(source[pos]=='e'||source[pos]=='E')){pos++;if(pos<source.Length&&(source[pos]=='+'||source[pos]=='-'))pos++;Digits();}v.Kind="number";v.Value=source.Substring(start,pos-start);return v;}
    void Digits(){int s=pos;while(pos<source.Length&&source[pos]>='0'&&source[pos]<='9')pos++;if(s==pos)Fail("Expected digit");}
    public static string Quote(string s){var b=new StringBuilder("\"");foreach(char c in s){switch(c){case '"':b.Append("\\\"");break;case '\\':b.Append("\\\\");break;case '\n':b.Append("\\n");break;case '\r':b.Append("\\r");break;case '\t':b.Append("\\t");break;default:if(c<32||char.IsSurrogate(c))b.Append("\\u"+((int)c).ToString("x4"));else b.Append(c);break;}}return b.Append('"').ToString();}
    public string Print(bool pretty){var b=new StringBuilder();Write(b,pretty,0);return b.ToString();}
    void Write(StringBuilder b,bool pretty,int level){if(Kind=="string"){b.Append(Quote(Value));return;}if(Kind!="object"&&Kind!="array"){b.Append(Value);return;}bool obj=Kind=="object";int count=obj?Members.Count:Items.Count;b.Append(obj?'{':'[');for(int i=0;i<count;i++){if(i>0)b.Append(',');if(pretty)b.AppendLine().Append(' ',(level+1)*2);if(obj)b.Append(Quote(Members[i].Key)).Append(pretty?": ":":");(obj?Members[i].Value:Items[i]).Write(b,pretty,level+1);}if(pretty&&count>0)b.AppendLine().Append(' ',level*2);b.Append(obj?'}':']');}
    public static void Diff(Json a,Json b,string path,List<string[]> rows){if(a.Kind!=b.Kind){rows.Add(new[]{"类型变化",path,a.Print(false),b.Print(false)});return;}if(a.Kind=="object"){var right=new Dictionary<string,Json>(StringComparer.Ordinal);foreach(var m in b.Members)right.Add(m.Key,m.Value);var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var m in a.Members){string p=path+"["+Quote(m.Key)+"]";Json r;if(right.TryGetValue(m.Key,out r))Diff(m.Value,r,p,rows);else rows.Add(new[]{"删除",p,m.Value.Print(false),""});seen.Add(m.Key);}foreach(var m in b.Members)if(!seen.Contains(m.Key))rows.Add(new[]{"新增",path+"["+Quote(m.Key)+"]","",m.Value.Print(false)});return;}if(a.Kind=="array"){for(int i=0;i<Math.Max(a.Items.Count,b.Items.Count);i++){string p=path+"["+i+"]";if(i>=a.Items.Count)rows.Add(new[]{"新增",p,"",b.Items[i].Print(false)});else if(i>=b.Items.Count)rows.Add(new[]{"删除",p,a.Items[i].Print(false),""});else Diff(a.Items[i],b.Items[i],p,rows);}return;}if(a.Value!=b.Value)rows.Add(new[]{"修改",path,a.Print(false),b.Print(false)});}
}

public class Toolbox : Form {
    readonly Color bg=Color.FromArgb(245,247,251), ink=Color.FromArgb(30,41,59), accent=Color.FromArgb(37,99,235);
    Panel body; Label status; TextBox input, output, left, right; DataGridView grid;
    public Toolbox(){Text="MyTool · 个人工具箱";Font=new Font("Microsoft YaHei UI",10);BackColor=bg;ForeColor=ink;AutoScaleMode=AutoScaleMode.Dpi;MinimumSize=new Size(900,620);StartPosition=FormStartPosition.CenterScreen;WindowState=FormWindowState.Maximized;
        var nav=new FlowLayoutPanel{Dock=DockStyle.Top,Height=66,Padding=new Padding(16,10,0,8),BackColor=Color.White};nav.Controls.Add(new Label{Text="MyTool / 个人工具箱",AutoSize=true,Padding=new Padding(0,11,24,0),Font=new Font(Font,FontStyle.Bold)});nav.Controls.Add(Button("首页",()=>Home()));nav.Controls.Add(Button("JSON 格式化",()=>Formatter()));nav.Controls.Add(Button("JSON Diff",()=>Differ()));
        status=new Label{Dock=DockStyle.Bottom,Height=34,Padding=new Padding(20,6,0,0),Text="所有处理均在本机完成 · 数据不会上传"};body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(24)};Controls.Add(body);Controls.Add(status);Controls.Add(nav);Home();}
    Button Button(string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=36,FlatStyle=FlatStyle.Flat,BackColor=Color.White,ForeColor=accent,Padding=new Padding(10,3,10,3),Margin=new Padding(4)};b.FlatAppearance.BorderColor=Color.FromArgb(210,220,235);b.Click+=(s,e)=>Safe(action);return b;}
    void Safe(Action action){try{action();}catch(Exception e){status.Text="操作失败："+e.Message;MessageBox.Show(this,e.Message,"请检查输入",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    Label Title(string text){return new Label{Text=text,Font=new Font(Font.FontFamily,22,FontStyle.Bold),Dock=DockStyle.Top,Height=60};}
    TextBox Editor(){return new TextBox{Multiline=true,AcceptsTab=true,AcceptsReturn=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill,Font=new Font("Consolas",11),BorderStyle=BorderStyle.FixedSingle,MaxLength=0};}
    Panel Pane(string title,Control editor){var p=new Panel{Dock=DockStyle.Fill,Padding=new Padding(6)};p.Controls.Add(editor);p.Controls.Add(new Label{Text=title,Dock=DockStyle.Top,Height=30});return p;}
    FlowLayoutPanel Bar(){return new FlowLayoutPanel{Dock=DockStyle.Top,Height=52};}
    void Home(){body.Controls.Clear();var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(0,30,0,0)};foreach(string name in new[]{"JSON 格式化","JSON Diff"}){bool format=name=="JSON 格式化";var b=Button(name+"\n\n"+(format?"校验、缩进与压缩 JSON":"按字段路径查看新增、删除和修改"),()=>{if(format)Formatter();else Differ();});b.Size=new Size(360,180);b.AutoSize=false;b.TextAlign=ContentAlignment.MiddleLeft;b.Font=new Font(Font.FontFamily,14);flow.Controls.Add(b);}body.Controls.Add(flow);body.Controls.Add(new Label{Text="日常开发的小工具，随开随用。",Dock=DockStyle.Top,Height=36});body.Controls.Add(Title("你的个人工具箱"));}
    void LoadInto(TextBox box){using(var d=new OpenFileDialog{Filter="JSON / 文本|*.json;*.txt|所有文件|*.*"})if(d.ShowDialog(this)==DialogResult.OK)box.Text=File.ReadAllText(d.FileName,Encoding.UTF8);}
    void Save(string text){if(text.Length==0)throw new InvalidOperationException("没有可保存的内容");using(var d=new SaveFileDialog{Filter="JSON 文件|*.json|文本文件|*.txt",FileName="result.json"})if(d.ShowDialog(this)==DialogResult.OK){File.WriteAllText(d.FileName,text,new UTF8Encoding(false));status.Text="已保存："+d.FileName;}}
    void Formatter(){body.Controls.Clear();input=Editor();output=Editor();output.ReadOnly=true;var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1};split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));split.Controls.Add(Pane("输入 JSON",input),0,0);split.Controls.Add(Pane("处理结果",output),1,0);var bar=Bar();bar.Controls.Add(Button("打开文件",()=>LoadInto(input)));bar.Controls.Add(Button("格式化",()=>Format(true)));bar.Controls.Add(Button("压缩",()=>Format(false)));bar.Controls.Add(Button("校验",()=>{Json.Parse(input.Text);status.Text="JSON 校验通过";}));bar.Controls.Add(Button("复制结果",()=>{if(output.TextLength>0)Clipboard.SetText(output.Text);}));bar.Controls.Add(Button("保存结果",()=>Save(output.Text)));bar.Controls.Add(Button("清空",()=>{input.Clear();output.Clear();}));body.Controls.Add(split);body.Controls.Add(bar);body.Controls.Add(Title("JSON 格式化"));}
    void Format(bool pretty){output.Clear();output.Text=Json.Parse(input.Text).Print(pretty);status.Text="处理完成 · "+output.TextLength+" 个字符";}
    void Differ(){body.Controls.Clear();left=Editor();right=Editor();var editors=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1};editors.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));editors.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));editors.Controls.Add(Pane("原始 JSON",left),0,0);editors.Controls.Add(Pane("新 JSON",right),1,0);grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,RowHeadersVisible=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,SelectionMode=DataGridViewSelectionMode.FullRowSelect};foreach(string c in new[]{"变化","JSON 路径","原始值","新值"})grid.Columns.Add(c,c);grid.Columns[0].FillWeight=35;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};layout.RowStyles.Add(new RowStyle(SizeType.Percent,55));layout.RowStyles.Add(new RowStyle(SizeType.Percent,45));layout.Controls.Add(editors,0,0);layout.Controls.Add(grid,0,1);var bar=Bar();bar.Controls.Add(Button("打开原始文件",()=>LoadInto(left)));bar.Controls.Add(Button("打开新文件",()=>LoadInto(right)));bar.Controls.Add(Button("比较差异",Compare));bar.Controls.Add(Button("交换两侧",()=>{var t=left.Text;left.Text=right.Text;right.Text=t;grid.Rows.Clear();}));bar.Controls.Add(Button("清空",()=>{left.Clear();right.Clear();grid.Rows.Clear();}));body.Controls.Add(layout);body.Controls.Add(bar);body.Controls.Add(Title("JSON Diff"));status.Text="忽略对象字段顺序；数组按索引比较；数字按原始写法比较（1 与 1.0 视为不同）";}
    void Compare(){grid.Rows.Clear();Json a,b;try{a=Json.Parse(left.Text);}catch(Exception e){throw new FormatException("原始 JSON："+e.Message);}try{b=Json.Parse(right.Text);}catch(Exception e){throw new FormatException("新 JSON："+e.Message);}var rows=new List<string[]>();Json.Diff(a,b,"$",rows);foreach(var row in rows){int i=grid.Rows.Add(row);grid.Rows[i].DefaultCellStyle.BackColor=row[0]=="新增"?Color.FromArgb(220,252,231):row[0]=="删除"?Color.FromArgb(254,226,226):Color.FromArgb(254,249,195);}status.Text=rows.Count==0?"两个 JSON 内容一致":"发现 "+rows.Count+" 处差异 · 可选中单元格复制";}
    [STAThread] public static int Main(string[] args){if(args.Length>0&&args[0]=="--self-test")return Tests.Run();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Toolbox());return 0;}
}

public static class Tests {
    public static int Run(){try{foreach(string bad in new[]{"", "01", "[1,]", "{\"a\":1,\"a\":2}", "1.", "true false", "\"\\x\"", "{\"a\" 1}"}){bool rejected=false;try{Json.Parse(bad);}catch(FormatException){rejected=true;}if(!rejected)throw new Exception("Accepted invalid JSON: "+bad);}string text="{\"n\":123456789012345678901234567890,\"s\":\"中文\\n\\uD83D\\uDE00\",\"a\":[true,null,-1.2e+3]}";var j=Json.Parse(text);if(Json.Parse(j.Print(true)).Print(false)!=j.Print(false))throw new Exception("Round trip failed");var rows=new List<string[]>();Json.Diff(Json.Parse("{\"a\":1,\"b\":[1,2],\"x\":true}"),Json.Parse("{\"b\":[1,3,4],\"a\":1,\"y\":null}"),"$",rows);if(rows.Count!=4)throw new Exception("Diff count failed");rows.Clear();Json.Diff(Json.Parse("{\"a\":1,\"b\":2}"),Json.Parse("{\"b\":2,\"a\":1}"),"$",rows);if(rows.Count!=0)throw new Exception("Object ordering failed");File.WriteAllText("test-results.txt","PASS: strict validation, lossless round trip, Unicode, structural diff, object ordering.");return 0;}catch(Exception e){File.WriteAllText("test-results.txt","FAIL: "+e);return 1;}}
}
